import json

WS = '/home/agent/workspace/rl_contract'
with open(f'{WS}/environment_spec.json') as f:
    spec = json.load(f)

valid_states = {tuple(s) for s in spec['states']}
valid_actions = {a['id'] for a in spec['actions']}

with open(f'{WS}/trajectories.jsonl') as f:
    lines = [l for l in f.read().splitlines() if l.strip()]

n_traj = len(lines)
total_transitions = 0
problems = []

for i, line in enumerate(lines, 1):
    t = json.loads(line)  # would raise on invalid JSON

    lens = {k: len(t.get(k, [])) for k in ('states', 'actions', 'rewards', 'dones')}
    if len(set(lens.values())) != 1:
        problems.append(f'T{i}: MISMATCHED array lengths: {lens}')
        continue  # can't safely index misaligned arrays

    n = lens['states']
    total_transitions += n

    for k, s in enumerate(t['states']):
        if tuple(s) not in valid_states:
            problems.append(f'T{i} step {k}: invalid state {s}')
    for k, a in enumerate(t['actions']):
        if a not in valid_actions:
            problems.append(f'T{i} step {k}: invalid action {a}')

    print(f'T{i}: {n} transitions, lengths {lens["states"]} across all arrays')

print()
print(f'Trajectories:        {n_traj}')
print(f'Total transitions:   {total_transitions}')
if problems:
    print(f'Problems found:      {len(problems)}')
    for p in problems:
        print(' -', p)
else:
    print('Array lengths:       all matched within every trajectory')
    print('States/actions:      all valid (no invalid values)')

